style.css:
/* Resize single-line text input fields */
input[type="text"] {
    width: 400px !important;
    height: 40px !important;
    font-size: 18px !important;
}

/* Resize multi-line textareas, if present */
textarea {
    width: 400px !important;
    height: 80px !important;
    font-size: 18px !important;
}
